"value\":1205.97,\"required\":false},{\"name\":\"top\",\"label\":\"上边距\",\"placeholder\":\"\",\"type\":\"el-input-number\",\"value\":98.03,\"required\":false},{\"name\":\"width\",\"label\":\"宽度\",\"placeholder\":\"该容器在1920px大屏中的宽度\",\"type\":\"el-input-number\",\"value\":675.57,\"required\":false},{\"name\":\"height\",\"label\":\"高度\",\"placeholder\":\"该容器在1080px大屏中的高度\",\"type\":\"el-input-number\",\"value\":340.92,\"required\":false}]}', NULL, 1, 0, 31, 'admin', '2024-05-06 11:29:21', 'admin', '2024-05-06 11:29:21', 1);
INSERT INTO `gaea_report_data_set` VALUES (74, 'foreign_turnover_2024', '查询对外贸易额', '查询对外贸易额', 'trade_data_board', 'SELECT value\r\nFROM pdf_index\r\nWHERE index_name LIKE \'The foreign trade turnover of Kazakhstan %\'\r\n        AND owner_pdf = \r\n    (SELECT pdf_num\r\n    FROM pdf_file\r\n    WHERE owner_num=5\r\n    ORDER BY  update_official DESC limit 1)', '[{\"value\":\"20 400.5 million\"}]', 1, 0, 'admin', '2024-05-05 13:21:41', 'admin', '2024-05-05 13:34:27', 3, 'sql');
INSERT INTO `gaea_report_data_set` VALUES (75, 'gdp', '查询2024年GDP', '', 'trade_data_board', 'SELECT value from index_detail where index_name=\'Gross domestic product\'', '[{\"value\":\"120 561 096,4\"}]', 1, 0, 'admin', '2024-05-05 13:47:57', 'admin', '2024-05-05 13:47:57', 1, 'sql');
INSERT INTO `gaea_report_data_set` VALUES (76, 'short_time_economic_indicator', '查询2024年短期经济指标', '', 'trade_data_board', 'SELECT value from index_detail where index_name=\'Short-term economic indicator\'', '[{\"value\":\"104,7\"}]', 1, 0, 'admin', '2024-05-05 13:50:23', 'admin', '2024-05-05 13:50:23', 1, 'sql');
INSERT INTO `gaea_report_data_set` VALUES (77, 'ipv_gdp', '2023年ipv_gdp', '', 'trade_data_board', 'SELECT value from index_detail where index_name=\'Volume index of Gross domestic product\'', '[{\"value\":\"105,1\"}]', 1, 0, 'admin', '2024-05-05 13:54:56', 'admin', '2024-05-05 13:55:15', 2, 'sql');
INSERT INTO `gaea_report_data_set` VALUES (78, 'export_import', '2024年进出口量对比', '', 'trade_data_board', 'SELECT \r\nREPLACE(SUBSTRING_INDEX(value, \' \', 2),\' \',\'\') as value,    \r\nCASE \r\n        WHEN index_name LIKE \'%export%\' THEN \'出口\'\r\n        WHEN index_name LIKE \'%import%\' THEN \'进口\'\r\n    END AS type\r\nFROM \r\n    pdf_index\r\nWHERE \r\n    (index_name LIKE \'%export%\' OR index_name LIKE \'%import%\')\r\n    AND owner_pdf = (\r\n        SELECT \r\n            pdf_num\r\n        FROM \r\n            pdf_file\r\n        WHERE \r\n            owner_num = 5\r\n        ORDER BY \r\n            update_official DESC\r\n        LIMIT 1\r\n    );', '[{\"type\":\"出口\",\"value\":\"12229.1\"}]', 1, 0, 'admin', '2024-05-05 15:24:32', 'admin', '2024-05-05 15:41:34', 2, 'sql');
INSERT INTO `gaea_report_data_set` VALUES (79, 'total_population', '2024总人口', '', 'trade_data_board', 'SELECT value\r\nFROM pdf_index\r\nWHERE index_name LIKE \'Total population%\'\r\n        AND owner_pdf = \r\n    (SELECT pdf_num\r\n    FROM pdf_file\r\n    WHERE owner_num=6 and pdf_name like\'Population of the Republic of Kazakhstan by gender and type of locality%\'\r\n    ORDER BY  update_official DESC limit 1)', '[{\"value\":\"20 033 842\"}]', 1, 0, 'admin', '2024-05-05 16:02:16', 'admin', '2024-05-05 16:02:16', 1, 'sql');
